//! Phosphor icons (MIT, https://phosphoricons.com) as the web draws them in the Tree and the Board: the web's `@phosphor-icons/react`
//! paths on their own 256 unit grid, filled with `currentColor`, so the glyphs match the web's to the pixel. The shell's own set
//! (`icons.rs`) stays the one place for everything else; these exist only where the web page is the spec.

use rune::Icon;

macro_rules! phosphor {
    ($name:ident, $id:literal, $body:literal) => {
        pub static $name: Icon = Icon { name: concat!("phosphor-", $id), view: 256.0, body: $body };
    };
}

